package com.lore.zzal.game;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lore.zzal.pet.*;import com.lore.zzal.pet.receipt.*;import com.lore.zzal.game.dto.*;import com.lore.common.exception.*;import tools.jackson.databind.json.JsonMapper;import java.time.*;import java.util.*;
class GameGuessDeliveryTest {
 final ZzalPetRepository owners=mock(ZzalPetRepository.class);final PetService pets=mock(PetService.class);final GameService games=mock(GameService.class);final ZzalGameRepository rows=mock(ZzalGameRepository.class);final ActionReceiptRepository receipts=mock(ActionReceiptRepository.class);final JsonMapper json=JsonMapper.builder().build();final ZzalPet pet=mock(ZzalPet.class);final ZzalGame game=mock(ZzalGame.class);final Instant now=Instant.parse("2026-10-18T12:00:00Z");final UUID id=UUID.randomUUID();
 GameGuessDeliveryService delivery(){return new GameGuessDeliveryService(owners,pets,games,rows,receipts,json);}
 GameRequests.Guess request(){return new GameRequests.Guess(GameRequests.Side.LEFT,id,0);}
 @BeforeEach void setup(){when(owners.findByIdForUpdate(2L)).thenReturn(Optional.of(pet));when(pet.isOwnedBy(1L)).thenReturn(true);when(rows.findByIdForUpdate(3L)).thenReturn(Optional.of(game));when(game.getUserId()).thenReturn(1L);when(game.getPetId()).thenReturn(2L);when(game.getId()).thenReturn(3L);}
 @Test void sameUuidReplaysFrozenRoundWithoutAnyGameEffect()throws Exception{var response=new GameResponses.Guess(3L,0,GameRequests.Side.LEFT,GameRequests.Side.RIGHT,false,0,false,null,1,5,3,2,List.of(),false);when(receipts.findByPetIdAndRequestId(2L,id)).thenReturn(Optional.of(new ActionReceipt(2L,id,"GAME_GUESS",GameGuessDeliveryService.hash(2L,3L,request()),json.writeValueAsString(response),now)));assertEquals(response,delivery().guess(1L,2L,3L,request(),now));verifyNoInteractions(games,rows);verify(receipts,never()).saveAndFlush(any());}
 @Test void careUuidCollisionRejectsBeforeEffects(){when(receipts.findByPetIdAndRequestId(2L,id)).thenReturn(Optional.of(new ActionReceipt(2L,id,"CARE_PET","x","{}",now)));assertThrows(BusinessException.class,()->delivery().guess(1L,2L,3L,request(),now));verifyNoInteractions(games,rows);}
 @Test void staleRoundCannotConsumeNextRound(){when(game.round()).thenReturn(1);assertThrows(BusinessException.class,()->delivery().guess(1L,2L,3L,request(),now));verifyNoInteractions(games);verify(receipts,never()).saveAndFlush(any());}
 @Test void existingSleepGuardFailureDoesNotWriteReceipt(){when(games.guess(1L,2L,3L,'L',now)).thenThrow(new BusinessException(ErrorCode.ZZAL_PET_SLEEPING));assertThrows(BusinessException.class,()->delivery().guess(1L,2L,3L,request(),now));verify(receipts,never()).saveAndFlush(any());}
 @Test void successCallsExistingEffectAndStoresExactRound(){when(games.guess(1L,2L,3L,'L',now)).thenReturn(new GameService.GuessResult(game,0,'L','R',false,List.of(),false));var out=delivery().guess(1L,2L,3L,request(),now);assertEquals(0,out.round());verify(games,times(1)).guess(1L,2L,3L,'L',now);verify(receipts).saveAndFlush(argThat(r->r.matches(GameGuessDeliveryService.hash(2L,3L,request()),"GAME_GUESS")));}
 @Test void identityBindsEveryPayloadField(){String hash=GameGuessDeliveryService.hash(2L,3L,request());assertNotEquals(hash,GameGuessDeliveryService.hash(2L,4L,request()));assertNotEquals(hash,GameGuessDeliveryService.hash(9L,3L,request()));assertNotEquals(hash,GameGuessDeliveryService.hash(2L,3L,new GameRequests.Guess(GameRequests.Side.RIGHT,id,0)));assertNotEquals(hash,GameGuessDeliveryService.hash(2L,3L,new GameRequests.Guess(GameRequests.Side.LEFT,id,1)));}
 @Test void partialIdentityRejectedAndLegacyConstructorPreserved(){assertTrue(new GameRequests.Guess(GameRequests.Side.LEFT).isIdentityPairValid());assertFalse(new GameRequests.Guess(GameRequests.Side.LEFT,id,null).isIdentityPairValid());assertFalse(new GameRequests.Guess(GameRequests.Side.LEFT,null,0).isIdentityPairValid());}
}
